// 单链表按位序插入，在第i个位置前插入元素e
Status ListInsert(LinkList *L, int i, ElemType e) {
    LinkList p = *L; int j = 0;
    while(p && j < i-1) { p = p->next; j++; }
    if(!p || j > i-1) return ERROR;
    LNode *s = (LNode*)malloc(sizeof(LNode));
    s->data = e; s->next = p->next;
    p->next = s;
    return OK;
}

// 头插法创建含n个节点的带头节点单链表
void CreateListHead(LinkList *L, int n) {
    *L = (LNode*)malloc(sizeof(LNode));
    (*L)->next = NULL;
    for(int i=0; i<n; i++) {
        LNode *p = (LNode*)malloc(sizeof(LNode));
        scanf("%d", &p->data);
        p->next = (*L)->next;
        (*L)->next = p;
    }
}

// 头插法反转单链表，原地逆置
LinkList ReverseList(LinkList L) {
    LNode *p = L->next, *q;
    L->next = NULL;
    while(p != NULL) {
        q = p->next;
        p->next = L->next;
        L->next = p;
        p = q;
    }
    return L;
}

// 双向链表在节点p之后插入新节点s
void DuListInsert(DuLNode *p, DuLNode *s) {
    s->prior = p;
    s->next = p->next;
    if(p->next != NULL) {
        p->next->prior = s;
    }
    p->next = s;
}

// 判断带头节点的循环单链表是否为空
int IsCirListEmpty(LinkList L) {
    return L->next == L;
}

// 删除单链表中所有值为e的节点
void ListDeleteAll(LinkList L, ElemType e) {
    LNode *p = L, *q;
    while(p->next != NULL) {
        if(p->next->data == e) {
            q = p->next;
            p->next = q->next;
            free(q);
        } else {
            p = p->next;
        }
    }
}

// 合并两个升序顺序表，结果存入C并保持升序
void MergeSqList(SqList A, SqList B, SqList *C) {
    int i=0, j=0, k=0;
    while(i<A.length && j<B.length) {
        if(A.data[i] <= B.data[j])
            C->data[k++] = A.data[i++];
        else
            C->data[k++] = B.data[j++];
    }
    while(i < A.length) C->data[k++] = A.data[i++];
    while(j < B.length) C->data[k++] = B.data[j++];
    C->length = k;
}

// 删除双向链表中的节点p，返回被删元素值
ElemType DuListDelete(DuLNode *p) {
    ElemType e = p->data;
    if(p->prior != NULL) p->prior->next = p->next;
    if(p->next != NULL) p->next->prior = p->prior;
    free(p);
    return e;
}

