// 广义表头尾链表节点定义
typedef enum {ATOM, LIST} ElemTag;
typedef struct GLNode {
    ElemTag tag;
    union {
        AtomType atom;
        struct { struct GLNode *hp, tp; } ptr;
    };
} GList;

// 广义表扩展线性链表节点定义
typedef enum {ATOM, LIST} ElemTag;
typedef struct GLNode {
    ElemTag tag;
    union {
        AtomType atom;
        struct GLNode hp;
    };
    struct GLNode tp;
} GList;

// 求广义表深度递归算法
int GListDepth(GList L) {
    if(!L) return 1;
    if(L->tag == ATOM) return 0;
    int max = 0;
    for(GList p = L; p; p = p->ptr.tp) {
        int dep = GListDepth(p->ptr.hp);
        if(dep > max) max = dep;
    }
    return max + 1;
}

// 求广义表深度递归算法
int GListDepth(GList L) {
    if(!L) return 1;
    if(L->tag==ATOM) return 0;
    int max=0;
    for(GList p=L->ptr.hp; p; p=p->tp){
        int d=GListDepth(p);
        if(d>max) max=d;
    }
    return max+1;
}

// 二叉链表节点定义
typedef struct BiTNode {
    TElemType data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

// 先序遍历递归算法
void PreOrder(BiTree T) {
    if(T) {
        visit(T->data);
        PreOrder(T->lchild);
        PreOrder(T->rchild);
    }
}

// 中序遍历递归算法
void InOrder(BiTree T) {
    if(T) {
        InOrder(T->lchild);
        visit(T->data);
        InOrder(T->rchild);
    }
}

// 后序遍历递归算法
void PostOrder(BiTree T) {
    if(T) {
        PostOrder(T->lchild);
        PostOrder(T->rchild);
        visit(T->data);
    }
}

// 层序遍历
void LevelOrder(BiTree T) {
    SqQueue Q; InitQueue(&Q);
    BiTree p;
    EnQueue(&Q, T);
    while(!QueueEmpty(Q)) {
        DeQueue(&Q, &p);
        visit(p->data);
        if(p->lchild) EnQueue(&Q, p->lchild);
        if(p->rchild) EnQueue(&Q, p->rchild);
    }
}

// 线索二叉树节点定义
typedef enum {Link, Thread} PointerTag;
typedef struct BiThrNode {
    TElemType data;
    struct BiThrNode *lchild, *rchild;
    PointerTag LTag, RTag;
} BiThrNode, *BiThrTree;

// 中序遍历非递归算法
void InOrderNonRec(BiTree T) {
    SqStack S; InitStack(&S);
    BiTree p = T;
    while(p || !StackEmpty(S)) {
        if(p) { Push(&S, p); p = p->lchild; }
        else { Pop(&S, &p); visit(p->data); p = p->rchild; }
    }
}

// 求二叉树深度递归算法
int TreeDepth(BiTree T) {
    if(!T) return 0;
    int left = TreeDepth(T->lchild);
    int right = TreeDepth(T->rchild);
    return left > right ? left+1 : right+1;
}

// 统计叶子节点数
int CountLeaf(BiTree T) {
    if(!T) return 0;
    if(!T->lchild && !T->rchild) return 1;
    return CountLeaf(T->lchild) + CountLeaf(T->rchild);
}

// 二叉树先序遍历递归实现
void PreOrder(BiTree T) {
    if(T) {
        visit(T->data);
        PreOrder(T->lchild);
        PreOrder(T->rchild);
    }
}

// 中序非递归遍历
void InOrderNonRec(BiTree T) {
    SqStack S; InitStack(&S);
    BiTree p=T;
    while(p||!StackEmpty(S)){
        if(p){ Push(&S,p); p=p->lchild; }
        else{ Pop(&S,&p); visit(p->data); p=p->rchild; }
    }
}

// 后序非递归遍历
void PostOrderNonRec(BiTree T) {
    SqStack S; InitStack(&S);
    BiTree p=T, pre=NULL;
    while(p||!StackEmpty(S)){
        if(p){ Push(&S,p); p=p->lchild; }
        else{
            GetTop(S,&p);
            if(p->rchild&&p->rchild!=pre) p=p->rchild;
            else{ Pop(&S,&p); visit(p->data); pre=p; p=NULL; }
        }
    }
}

