// 直接插入排序
void InsertSort(SqList &L){
    for(int i=2;i<=L.length;i++){
        L.r[0]=L.r[i];
        int j;
        for(j=i-1;j>0 && L.r[0].key<L.r[j].key;j--)
            L.r[j+1]=L.r[j];
        L.r[j+1]=L.r[0];
    }
}

// 希尔排序示例
void ShellSort(SqList &L,int dlta[],int t){
    for(int k=0;k<t;k++){
        int d=dlta[k];
        for(int i=d+1;i<=L.length;i++){
            L.r[0]=L.r[i];
            int j;
            for(j=i-d;j>0 && L.r[0].key<L.r[j].key;j-=d)
                L.r[j+d]=L.r[j];
            L.r[j+d]=L.r[0];
        }
    }
}

// 简单选择排序
void SelectSort(SqList &L){
    for(int i=1;i<L.length;i++){
        int min=i;
        for(int j=i+1;j<=L.length;j++)
            if(L.r[j].key<L.r[min].key) min=j;
        if(min!=i) swap(L.r[i],L.r[min]);
    }
}

// 两路归并核心合并函数
void Merge(SqList &L,int low,int mid,int high){
    int i=low,j=mid+1,k=0;
    while(i<=mid && j<=high){
        if(L.r[i].key<=L.r[j].key) L.r[++k]=L.r[i++];
        else L.r[++k]=L.r[j++];
    }
    while(i<=mid) L.r[++k]=L.r[i++];
    while(j<=high) L.r[++k]=L.r[j++];
    for(i=0;i<k;i++) L.r[low+i]=L.r[i+1];
}

// 直接插入排序
void InsertSort(SqList *L){
    for(int i=2;i<=L->length;i++){
        if(L->r[i].key<L->r[i-1].key){
            L->r[0]=L->r[i];
            int j;
            for(j=i-1;L->r[0].key<L->r[j].key;j--)
                L->r[j+1]=L->r[j];
            L->r[j+1]=L->r[0];
        }
    }
}

// 冒泡排序
void BubbleSort(SqList *L){
    for(int i=1;i<L->length;i++){
        int flag=0;
        for(int j=1;j<=L->length-i;j++){
            if(L->r[j].key>L->r[j+1].key){
                swap(L,j,j+1); flag=1;
            }
        }
        if(flag==0) break;
    }
}

// 快速排序
void QuickSort(SqList *L, int low, int high){
    if(low<high){
        int pivot=Partition(L,low,high);
        QuickSort(L,low,pivot-1);
        QuickSort(L,pivot+1,high);
    }
}
int Partition(SqList *L, int low, int high){
    L->r[0]=L->r[low];
    KeyType p=L->r[low].key;
    while(low<high){
        while(low<high&&L->r[high].key>=p) high--;
        L->r[low]=L->r[high];
        while(low<high&&L->r[low].key<=p) low++;
        L->r[high]=L->r[low];
    }
    L->r[low]=L->r[0];
    return low;
}

// 堆排序（大根堆调整）
void HeapAdjust(SqList *L, int s, int m){
    ElemType rc=L->r[s];
    for(int j=2*s;j<=m;j*=2){
        if(j<m&&L->r[j].key<L->r[j+1].key) j++;
        if(rc.key>=L->r[j].key) break;
        L->r[s]=L->r[j]; s=j;
    }
    L->r[s]=rc;
}
void HeapSort(SqList *L){
    for(int i=L->length/2;i>0;i--)
        HeapAdjust(L,i,L->length);
    for(int i=L->length;i>1;i--){
        swap(L,1,i);
        HeapAdjust(L,1,i-1);
    }
}

// 败者树多路归并核心逻辑伪代码
// b[]存放败者段编号，ls[]叶子节点对应k个归并段当前记录
void CreateLoserTree(int ls[],int b[],int k){
    for(int i=0;i<k;i++) b[k+i]=i;
    for(int i=k‑1;i>0;i--) Adjust(ls,b,i);
}
void Adjust(int ls[],int b[],int s){
    int t=(s+k)/2;
    while(t>0){
        if(ls[b[s]]>ls[b[t]]){ int tmp=b[s];b[s]=b[t];b[t]=tmp; s=t; }
        else break;
        t=t/2;
    }
}
